import{a as e,i as t,r as n,t as r}from"./app-BSn6oFAa.js";var i=JSON.parse(`{"path":"/guide/maimai.html","title":"舞萌 DX（maimai）","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"guide/maimai.md"}`),a={name:`maimai.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="舞萌-dx-maimai" tabindex="-1"><a class="header-anchor" href="#舞萌-dx-maimai"><span>舞萌 DX（maimai）</span></a></h1><p>歌曲名、用户名等包含空格的参数可使用中文引号包裹。</p><h2 id="曲库与谱面" tabindex="-1"><a class="header-anchor" href="#曲库与谱面"><span>曲库与谱面</span></a></h2><table><thead><tr><th>指令 / 格式</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>查歌</code></td><td><code>歌名 [页码]</code></td><td><code>.查歌 初音</code></td><td>按歌名搜索；结果较少时直接列出，单曲时发送谱面信息卡，结果较多时发送分页图片</td></tr><tr><td><code>定数查歌</code></td><td><code>定数</code> / <code>最小定数 最大定数 [页码]</code></td><td><code>.定数查歌 13+</code></td><td>按谱面定数搜索歌曲</td></tr><tr><td><code>bpm查歌</code></td><td><code>BPM</code> / <code>最小BPM 最大BPM [页码]</code></td><td><code>.bpm查歌 180 200</code></td><td>按 BPM 搜索歌曲</td></tr><tr><td><code>曲师查歌</code></td><td><code>曲师名 [页码]</code></td><td><code>.曲师查歌 某某</code></td><td>按作曲 / 曲师搜索歌曲</td></tr><tr><td><code>谱师查歌</code></td><td><code>谱师名 [页码]</code></td><td><code>.谱师查歌 某某</code></td><td>按谱面设计者搜索歌曲</td></tr><tr><td><code>&lt;别名&gt;是什么歌</code> / <code>&lt;别名&gt;是啥歌</code></td><td><code>[页码]</code></td><td><code>.绿谱是什么歌</code></td><td>查询歌曲别名；别名重复时列出歌曲 ID</td></tr><tr><td><code>id</code></td><td><code>歌曲 ID</code></td><td><code>.id 12345</code></td><td>按歌曲 ID 查询谱面信息卡</td></tr><tr><td><code>minfo</code> / <code>Minfo</code> / <code>info</code></td><td><code>歌曲 ID / 歌名 / 别名</code></td><td><code>.minfo 12345</code></td><td>查询自己的指定歌曲成绩；需要已绑定水鱼或落雪账号</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p><code>查歌</code> 的类型也可以写作 <code>定数查歌</code>、<code>bpm查歌</code>、<code>曲师查歌</code>、<code>谱师查歌</code>。歌曲列表每页最多 25 首；谱面信息卡会显示曲名、作者、BPM、版本、难度、定数、谱师和物量等信息。</p></div><h2 id="玩家成绩与账号绑定" tabindex="-1"><a class="header-anchor" href="#玩家成绩与账号绑定"><span>玩家成绩与账号绑定</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>b50</code> / <code>B50</code></td><td><code>[水鱼用户名]</code></td><td><code>.b50</code> 或 <code>.b50 玩家名</code></td><td>查询自己的 Best 50；也可指定水鱼用户名</td></tr><tr><td><code>ap50</code> / <code>AP50</code></td><td>无</td><td><code>.ap50</code></td><td>查询 All Perfect 50（仅落雪查分器支持）</td></tr><tr><td><code>绑定水鱼</code> / <code>水鱼绑定</code> / <code>bindmaimai</code></td><td>无</td><td><code>.绑定水鱼</code></td><td>生成水鱼 OAuth 绑定链接；链接有效期 10 分钟</td></tr><tr><td><code>绑定落雪</code> / <code>落雪绑定</code> / <code>bindlxns</code></td><td>无</td><td><code>.绑定落雪</code></td><td>生成落雪 OAuth 授权链接（权限：读取玩家数据）</td></tr><tr><td><code>数据源</code> / <code>maimai数据源</code></td><td><code>自动/水鱼/落雪</code></td><td><code>.数据源 落雪</code></td><td>设置自己的数据源偏好</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p>数据源偏好（按用户独立存储，仅影响自己的查询）：</p><ul><li><code>自动</code>（默认）：水鱼优先，失败自动切换落雪</li><li><code>水鱼</code>：查询优先使用水鱼查分器</li><li><code>落雪</code>：查询优先使用落雪查分器</li></ul><p>当实际使用的数据源与偏好不一致时，会附带提示「本次查询使用的数据源：水鱼 / 落雪」。</p><p><code>ap50</code> 仅落雪支持；<code>绑定水鱼</code>、牌子查询仅水鱼支持，不受数据源偏好影响。</p></div><h2 id="定数表与完成表" tabindex="-1"><a class="header-anchor" href="#定数表与完成表"><span>定数表与完成表</span></a></h2><table><thead><tr><th>指令 / 格式</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>&lt;等级&gt;定数表</code></td><td>等级 <code>7</code> 至 <code>15</code>（可带 <code>+</code>）</td><td><code>.13+定数表</code></td><td>发送指定等级的定数表；低于 7 的等级不支持</td></tr><tr><td><code>&lt;等级&gt;[fc/fc+/ap/ap+]完成表</code></td><td>等级 <code>7</code> 至 <code>15</code>，可选完成计划</td><td><code>.13ap完成表</code></td><td>查询指定等级的成绩完成表；可选 FC / AP 计划</td></tr><tr><td><code>&lt;版本&gt;&lt;牌子&gt;完成表</code></td><td>版本 + 牌子 + 可选页码</td><td><code>.紫将完成表</code></td><td>查询指定版本牌子完成表</td></tr><tr><td><code>&lt;版本&gt;&lt;牌子&gt;进度表</code></td><td>版本 + 牌子 + 可选页码</td><td><code>.紫将进度</code></td><td>查询指定版本牌子进度</td></tr><tr><td><code>&lt;等级&gt; &lt;评价&gt;进度</code></td><td>等级、评价、可选分类和页码</td><td><code>.13 s 进度</code></td><td>查询指定等级的评价进度</td></tr><tr><td><code>&lt;定数&gt;分数列表</code></td><td>定数 + 可选页码</td><td><code>.13.0分数列表</code></td><td>查询指定定数的分数列表</td></tr></tbody></table><h3 id="牌子版本与评价" tabindex="-1"><a class="header-anchor" href="#牌子版本与评价"><span>牌子版本与评价</span></a></h3><div class="hint-container tip"><p class="hint-container-title">提示</p><p>牌子版本支持真、超、檄、橙、暁/晓、桃、櫻/樱、紫、菫/堇、白、雪、輝/辉、舞/霸、熊、華/华、爽、煌、宙、星、祭、祝、双、宴、镜、彩等写法。牌子计划常用 <code>者</code>、<code>極/极</code>、<code>将</code>、<code>神</code>、<code>舞舞</code>。</p><p>评价进度支持评价等级（如 <code>s</code>、<code>ss</code>、<code>sss</code>、<code>ap</code>、<code>fc</code>、<code>fs</code>、<code>fdx</code> 及其 <code>+</code> 写法），分类可选 <code>已完成</code>、<code>未完成</code>、<code>未开始</code> / <code>未游玩</code>。</p></div>`,12)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};